import {icon} from './icons.js';
import {cleanupMotion,cleanupDashboardMotion,enhanceMotion} from './motion.js';
import {events,locations as demoLocations,seedReports} from './data.js';
import {request,setToken} from './api.js';
const demo=window.MONSOON_CONFIG.DEMO_MODE;
let reports=demo?seedReports():[], locations=demo?demoLocations:[], page='Overview',period=7,location='',event='',status='',search='',offset=0,utc=false,staff=demo,role=demo?'admin':null,loading=false,error='',zoom=1,lastSync=new Date();
const saved=demo?localStorage.getItem('monsoon-reviews'):null;
if(saved){try{const changes=JSON.parse(saved);reports.forEach(r=>Object.assign(r,changes[r.id]||{}));}catch{}}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={Overview:icon('overview'),'Event explorer':icon('explore'),Analytics:icon('analytics'),'Review queue':icon('review'),'Data sources':icon('source'),Settings:icon('settings')};
const badge=r=>`<span class="badge ${esc(r.status)}">${r.status==='verified'?'Verified by reviewer':r.status==='pending'?'Pending review':'Rejected'}</span>`;
const time=t=>new Date(t).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',...(utc?{timeZone:'UTC'}:{})});
function filtered({ignoreLocation=false}={}){return reports.filter(r=>(Date.now()-Date.parse(r.event_time)<period*86400000)&&(ignoreLocation||!location||String(r.location?.id)===location)&&(!event||r.event_type===event)&&(!status||r.status===status)&&(!search||`${r.description} ${r.location_name} ${r.id}`.toLowerCase().includes(search.toLowerCase()))&&(page!=='Review queue'||r.status==='pending')&&(staff||r.status==='verified'));}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function render(){cleanupMotion();const data=filtered(); const pending=reports.filter(r=>r.status==='pending').length;
$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Monsoon overview"><span class="brandmark">${icon('logo')}</span>monsoon<span class="brand-dot">.</span></a><div class="workspace"><span class="workspace-icon">M</span><div>Weather intelligence<small>India observatory</small></div><span>⌄</span></div><p class="nav-label">WORKSPACE</p><nav>${['Overview','Event explorer','Analytics'].map(nav).join('')}</nav><p class="nav-label">ADMINISTRATION</p><nav>${(staff?['Review queue','Data sources']:['Data sources']).map(nav).join('')}</nav><div class="sidebar-bottom"><div class="network"><span class="dot"></span>${demo?'Demo workspace':'API connection'}<small>${demo?'Sample data. Real possibilities.':'Refreshes every 30 seconds'}</small></div><button data-page="Settings" aria-label="Settings and connection" class="nav-button">${icon('settings')} <span>Settings & connection</span></button><div class="profile"><span class="avatar">${staff?'AK':'GU'}</span><div>${staff?'Analyst workspace':'Public workspace'}<small>${demo?'Demo administrator':staff?'Staff session':'Verified reports only'}</small></div><button id="session" title="Change session">↗</button></div></div></aside><div class="scroll-progress" aria-hidden="true"></div><div class="main"><header class="topbar"><div><span class="crumb">Workspace</span><span class="slash">/</span>${esc(page)}</div><div class="top-actions"><span class="mode">${demo?'Demo data':'Connected API'}</span><button id="theme-toggle" class="theme-toggle" aria-label="Toggle dark and light mode" aria-pressed="${document.documentElement.dataset.theme==='light'}"><span aria-hidden="true">◐</span><span class="theme-label">${document.documentElement.dataset.theme==='light'?'Dark':'Light'}</span></button><button id="refresh" aria-label="Refresh data">${icon('refresh')}</button><span class="avatar small">${staff?'AK':'GU'}</span></div></header><main>${page==='Overview'?'<section id="signal-hero" class="signal-hero" aria-label="Monsoon observatory"></section>':`<div class="page-heading"><div><h1>${page==='Overview'?'A clearer view of the weather.':page==='Review queue'?'Every report deserves a closer look.':page==='Analytics'?'Patterns beyond the forecast.':page==='Event explorer'?'Follow the events on the ground.':page==='Data sources'?'Know where your data comes from.':'Your observation workspace.'}</h1><p>${page==='Overview'?'Monitor events, connect the signals, and find the reports you can trust.':page==='Review queue'?'Review evidence and make the final call. AI suggestions are not verification.':page==='Data sources'?'Source provenance, freshness, and ingestion at a glance.':'Explore weather intelligence with context and traceable sources.'}</p></div><button class="button" id="export">${icon('down')} <span>Export data</span></button></div>`}${demo?'<div class="demo-note">Interactive preview <span>All reports, AI suggestions, and source metrics are sample data.</span></div>':''}${page==='Settings'?settings():page==='Data sources'?sources():`<div id="dashboard-region">${dashboardContent()}</div>`}<footer><span>monsoon <span class="footer-dot">/</span> Weather intelligence, with provenance.</span><span>Last refreshed ${lastSync.toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})} · ${demo?'Demo mode':'30s refresh'}</span></footer></main></div>`;
function nav(n){return `<button class="nav-button ${page===n?'active':''}" data-page="${n}" aria-label="${n}" aria-current="${page===n?'page':'false'}"><span class="nav-icon">${icons[n]}</span><span class="nav-label-roll"><span>${n}</span><span aria-hidden="true">${n}</span></span>${n==='Review queue'?`<span class="count">${pending}</span>`:''}${page===n?`<span class="nav-arrow">${icon('arrow')}</span>`:''}</button>`;}
bind();enhanceMotion(page);}

function dashboardContent(){const data=filtered();return `${filters()}${error?`<div class="error" role="alert">${esc(error)} <button id="retry">Retry</button></div>`:''}${loading&&!reports.length?'<div class="empty" role="status">Loading weather reports…</div>':`${metrics(data)}${page==='Overview'?`<div class="visual-grid">${map(data)}${distribution(data)}</div>`:page==='Analytics'?`<div class="visual-grid">${trend(data)}${distribution(data)}</div>`:''}${table(data)}`}`;}
function renderDashboard({focusLocation,focusId}={}){const region=$('#dashboard-region');if(!region){render();return;}const y=window.scrollY;cleanupDashboardMotion();region.innerHTML=dashboardContent();const count=document.querySelector('.nav-button[data-page="Review queue"] .count');if(count)count.textContent=reports.filter(r=>r.status==='pending').length;bind();enhanceMotion(page,{dashboardOnly:true});window.scrollTo({top:y,behavior:'instant'});if(focusLocation)document.querySelector('[data-loc="'+focusLocation+'"]')?.focus({preventScroll:true});else if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}

function filters(){return `<div class="section-label"><h2>The observatory.</h2>${page==='Overview'?`<button class="button" id="export">${icon('down')} Export data</button>`:''}</div><section class="filters" aria-label="Report filters"><div class="period">${[1,7,30].map(n=>`<button data-period="${n}" aria-pressed="${period===n}" class="${period===n?'selected':''}">${n===1?'24 hours':n+' days'}</button>`).join('')}</div><label><select id="location" aria-label="Location"><option value="">All locations</option>${locations.map(l=>`<option value="${l.id}" ${String(l.id)===location?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label><select id="event" aria-label="Event type"><option value="">All events</option>${Object.entries(events).map(([k,v])=>`<option value="${k}" ${event===k?'selected':''}>${v}</option>`).join('')}</select></label>${staff?`<label><select id="status" aria-label="Verification status"><option value="">All statuses</option>${['verified','pending','rejected'].map(v=>`<option ${status===v?'selected':''} value="${v}">${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></label>`:''}<button class="text-button" id="reset">Reset filters</button><span class="filter-date">${new Date(Date.now()-period*86400000).toLocaleDateString('en-IN',{day:'numeric',month:'short'})} – ${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</span></section>`;}
function metrics(data){const verified=data.filter(r=>r.status==='verified').length,pending=data.filter(r=>r.status==='pending').length;return `<section class="metrics"><article><div>Total reports <span>▤</span></div><strong>${data.length.toLocaleString()}</strong><small>Selected period</small></article><article><div>Verified reports <span>☑</span></div><strong>${verified}<em class="metric-badge">${data.length?Math.round(verified/data.length*100):0}%</em></strong><small>Reviewed by a human</small></article><article><div>Awaiting review <span>◷</span></div><strong>${pending}<em class="amber-text">Pending</em></strong><small>Requires assessment</small></article><article><div>Active locations <span>⌖</span></div><strong>${new Set(data.map(r=>r.location?.id)).size}<em>/ ${locations.length}</em></strong><small>Locations with reported events</small></article></section>`;}
function map(data){const contextual=filtered({ignoreLocation:true});let groups=locations.map(l=>({...l,count:contextual.filter(r=>r.location?.id===l.id).length})).filter(l=>l.count||String(l.id)===location);return `<section class="panel map-panel"><div class="panel-head"><div><h2>Weather on the ground</h2><p>Event activity across India</p></div><span class="badge verified"><span class="dot"></span>${groups.length} locations</span></div><div class="map-stage"><svg class="geo" viewBox="0 0 760 380" role="group" aria-label="Schematic geographic locator of Indian cities; not a boundary map"><defs><pattern id="grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M35 0H0V35" fill="none" stroke="currentColor" stroke-width=".4"/></pattern></defs><rect width="760" height="380" fill="url(#grid)"/><g class="contours"><path d="M-30 300Q80 160 180 220T400 200T780 90M-30 325Q90 170 190 240T420 220T780 115M-30 350Q100 190 200 260T440 240T780 140M-30 375Q110 210 210 280T460 260T780 165M-30 400Q120 230 220 300T480 280T780 190M-30 425Q130 250 230 320T500 300T780 215"/></g><g transform="translate(${380-380*zoom} ${190-190*zoom}) scale(${zoom})"><path class="land" d="M285 20L326 37L347 65L368 69L376 91L411 97L434 122L476 131L503 128L523 110L557 112L551 137L522 156L495 151L478 173L446 170L421 190L406 212L384 227L366 257L353 280L337 316L325 332L312 317L301 288L287 266L279 236L267 213L247 184L228 174L213 149L236 139L245 112L264 100L273 78L264 56Z"/><path class="internal" d="M273 78L330 100L376 91M245 112L304 138L347 111L411 97M236 139L290 165L334 148L376 173L434 122M267 213L315 202L334 148M287 266L333 244L384 227M301 288L353 280M290 165L315 202L333 244M376 173L366 219L406 212"/>${groups.map(l=>{const x=250+(l.longitude-72)*14,y=70+(30-l.latitude)*12;return `<g class="marker ${String(l.id)===location?'is-selected':''}" data-loc="${l.id}" tabindex="0" role="button" aria-pressed="${String(l.id)===location}" aria-label="Filter ${esc(l.name)}, ${l.count} reports"><circle cx="${x}" cy="${y}" r="25" class="selection-ring"/><circle cx="${x}" cy="${y}" r="20" class="halo"/><circle cx="${x}" cy="${y}" r="10"/><text x="${x}" y="${y+4}" class="marker-count">${l.count}</text><text x="${l.name==='Bengaluru'?x-16:x+16}" y="${y+4}" text-anchor="${l.name==='Bengaluru'?'end':'start'}" class="city-label">${esc(l.name)}</text></g>`;}).join('')}</g></svg><span class="sea sea-left">ARABIAN<br>SEA</span><span class="sea sea-right">BAY OF<br>BENGAL</span><div class="map-key"><span class="dot"></span> Report cluster <span>Size shows activity</span></div><div class="zoom"><button id="zoom-in" aria-label="Zoom in">+</button><button id="zoom-out" aria-label="Zoom out">−</button></div><span class="map-disclaimer">Schematic locator · Not a boundary map</span></div><div class="map-footer"><div class="map-location"><span> ${location?esc(locations.find(l=>String(l.id)===location)?.name):'India'} <span class="muted">/ ${data.length} reports in view</span></span>${location?'<button id="clear-location" class="location-clear" aria-label="Clear selected location">Clear selection ×</button>':''}</div><button class="text-button" data-page="Event explorer">Explore reports ${icon('arrow')}</button></div></section>`;}
function distribution(data){const counts=Object.entries(events).map(([k,v])=>({k,v,n:data.filter(r=>r.event_type===k).length})).filter(x=>x.n).sort((a,b)=>b.n-a.n);let stop=0;const fills=['var(--accent)','var(--chart-mid)','var(--chart-soft)','var(--line)'];const segments=counts.map((c,i)=>{const start=stop;stop+=c.n/(data.length||1)*100;return `${fills[Math.min(i,3)]} ${start}% ${stop}%`;}).join(',');return `<section class="panel distribution"><div class="panel-head"><div><h2>Event breakdown</h2><p>Reports by event type</p></div></div><div class="donut" style="background:${data.length?`conic-gradient(${segments})`:'var(--line)'}"><div><strong>${data.length}</strong><span>total events</span></div></div><div class="event-bars">${counts.map((c,i)=>`<button data-event="${c.k}"><span class="legend-dot tone-${i}"></span><span>${c.v}</span><strong>${c.n}</strong><span class="muted">${Math.round(c.n/data.length*100)}%</span></button>`).join('')||'<p>No events in this selection.</p>'}</div><div class="distribution-footer">Categorization ${demo?'preview':'from reports'} <span>✧</span></div></section>`;}
function table(data){const sorted=[...data].sort((a,b)=>page==='Review queue'?Date.parse(a.event_time)-Date.parse(b.event_time):Date.parse(b.event_time)-Date.parse(a.event_time));const list=sorted.slice(offset,offset+6);return `<section class="panel reports"><div class="panel-head"><div><h2>${page==='Review queue'?'Moderation queue':'Latest event reports'} <span class="inline-count">${data.length}</span></h2><p>${page==='Review queue'?'Oldest reports first. Open a report to review evidence.':'Citizen reports in the selected period.'}</p></div><div class="table-tools"><label class="search">${icon('search')} <input id="search" placeholder="Search reports…" aria-label="Search reports" value="${esc(search)}"></label><button id="utc" class="button">${utc?'UTC':'Local time'}</button></div></div><div class="table-scroll"><table><thead><tr><th>Event</th><th>Location</th><th>Event time</th><th>Severity</th><th>Verification</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><button class="report-link" data-report="${esc(r.id)}"><span class="weather-icon">${icon(r.event_type==='heavy_rain'?'rain':r.event_type==='heatwave'?'sun':'wind')}</span><span>${esc(events[r.event_type]||r.event_type)}<small>${esc(r.id)} · Citizen report</small></span></button></td><td>${esc(r.location?.name||r.location_name||'Unassigned')}<small>India</small></td><td>${time(r.event_time)}<small>${utc?'UTC':Intl.DateTimeFormat().resolvedOptions().timeZone}</small></td><td><span class="severity ${r.severity}">● ${esc(r.severity||'Not specified')}</span></td><td>${badge(r)}</td><td><button data-report="${esc(r.id)}" aria-label="Open report ${esc(r.id)}">${icon('diagonal')}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No reports match these filters.<br><button id="empty-reset">Clear filters</button></div></td></tr>'}</tbody></table></div><div class="table-footer"><span>${data.length?offset+1:0}–${Math.min(offset+6,data.length)} of ${data.length} reports</span><div><button id="prev" ${offset===0?'disabled':''}>← Previous</button><button id="next" ${offset+6>=data.length?'disabled':''}>Next →</button></div></div></section>`;}
function trend(data){const days=Array.from({length:period},(_,i)=>{const d=new Date(Date.now()-(period-i-1)*86400000);return {label:d.toLocaleDateString('en-IN',{day:'numeric',month:'short'}),n:data.filter(r=>new Date(r.event_time).toDateString()===d.toDateString()).length};});const max=Math.max(1,...days.map(d=>d.n));return `<section class="panel trend"><div class="panel-head"><div><h2>Reports over time</h2><p>Daily report counts · All selected events</p></div></div><div class="bar-chart">${days.map(d=>`<div class="bar-column"><span>${d.n}</span><div style="height:${d.n/max*190}px" title="${d.label}: ${d.n} reports"></div><small>${period<=7?d.label:''}</small></div>`).join('')}</div><p class="chart-caption">${data.length} reports over ${period} days. Bars show report volume, not weather measurements.</p></section>`;}
function sources(){return `<section class="panel"><div class="panel-head"><div><h2>Connected data sources</h2><p>${demo?'Illustrative source health. No ingestion worker is connected.':'Source status from your backend.'}</p></div></div><div id="source-content">${demo?sourceRows([{display_name:'Open-Meteo',name:'open_meteo',freshness:'fresh',trust_level:'provider_model',attribution_text:'Weather data by Open-Meteo',last_success_at:new Date().toISOString()},{display_name:'data.gov.in',name:'data_gov',freshness:'stale',trust_level:'official',attribution_text:'Government Open Data Platform India',last_success_at:new Date(Date.now()-86400000).toISOString()},{display_name:'Citizen reports',name:'citizen',freshness:'fresh',trust_level:'citizen',attribution_text:'Community-submitted reports',last_success_at:new Date().toISOString()}]):'<div class="empty">Loading source status…</div>'}</div></section><div class="trust-note"><h2>A source is not a verdict.</h2><p>Open-Meteo data is model-derived, not station readings or official observations. Citizen reports are only verified after human review. News items are not verified observations.</p></div>`;}
function sourceRows(items){return items.map(s=>`<article class="source-row"><span class="source-symbol">◈</span><div><h3>${esc(s.display_name)}</h3><p>${esc(s.attribution_text||s.name)}</p></div><span class="badge">${s.trust_level==='provider_model'?'Model-derived observation':s.trust_level==='official'?'Official data':'Citizen reports'}</span><span class="freshness">● ${esc(s.freshness)}</span><small>${s.last_success_at?time(s.last_success_at):'No data yet'}</small></article>`).join('')||'<div class="empty">No sources configured.</div>';}
function settings(){return `<section class="panel settings"><h2>Connection & session</h2><p>${demo?'You are exploring a demo. Review changes are saved in this browser only.':'The frontend is connected to your configured API.'}</p><dl><dt>Data mode</dt><dd>${demo?'Demonstration':'Live API'}</dd><dt>API base URL</dt><dd>${esc(window.MONSOON_CONFIG.API_BASE_URL)}</dd><dt>Refresh interval</dt><dd>30 seconds</dd><dt>Session</dt><dd>${staff?'Administrator preview / staff':'Public'}</dd></dl><p>Connection configuration lives in <code>dist/config.js</code>. Set DEMO_MODE to false and API_BASE_URL to your backend origin.</p><button id="login" class="primary">${demo?'Switch to public preview':'Staff login'}</button></section>`;}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{const changed=page!==b.dataset.page;page=b.dataset.page;offset=0;render();if(changed)window.scrollTo({top:0,behavior:'instant'});if(page==='Data sources'&&!demo)loadSources();});$('.brand').onclick=e=>{e.preventDefault();page='Overview';render();window.scrollTo({top:0,behavior:'instant'});}; document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=+b.dataset.period;offset=0;renderDashboard();if(!demo)load();});['location','event','status'].forEach(id=>{if($('#'+id))$('#'+id).onchange=e=>{if(id==='location')location=e.target.value;if(id==='event')event=e.target.value;if(id==='status')status=e.target.value;offset=0;renderDashboard();};});
['reset','empty-reset'].forEach(id=>{if($('#'+id))$('#'+id).onclick=()=>{location=event=status=search='';offset=0;renderDashboard();};});
document.querySelectorAll('[data-loc]').forEach(b=>{const select=()=>{const id=b.dataset.loc;location=location===id?'':id;offset=0;renderDashboard({focusLocation:id});};b.onclick=select;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select();}};});document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{event=b.dataset.event;offset=0;renderDashboard();});
if($('#search'))$('#search').oninput=e=>{search=e.target.value;offset=0;const pos=e.target.selectionStart;renderDashboard();$('#search').focus({preventScroll:true});$('#search').setSelectionRange(pos,pos);};
document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>openReport(b.dataset.report));
if($('#prev'))$('#prev').onclick=()=>{offset=Math.max(0,offset-6);renderDashboard({focusId:'prev'});};if($('#next'))$('#next').onclick=()=>{offset+=6;renderDashboard({focusId:'next'});};if($('#utc'))$('#utc').onclick=()=>{utc=!utc;renderDashboard({focusId:'utc'});};
if($('#zoom-in'))$('#zoom-in').onclick=()=>{zoom=Math.min(1.8,zoom+.2);renderDashboard({focusId:'zoom-in'});};if($('#zoom-out'))$('#zoom-out').onclick=()=>{zoom=Math.max(.8,zoom-.2);renderDashboard({focusId:'zoom-out'});};
if($('#clear-location'))$('#clear-location').onclick=()=>{location='';offset=0;renderDashboard();};$('#theme-toggle').onclick=()=>{const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';$('#theme-toggle').setAttribute('aria-pressed',String(light));$('.theme-label').textContent=light?'Dark':'Light';try{localStorage.setItem('monsoon-theme',light?'light':'dark');}catch{}};$('#refresh').onclick=()=>load(true);if($('#retry'))$('#retry').onclick=()=>load();if($('#export'))$('#export').onclick=exportCSV;$('#session').onclick=login;if($('#login'))$('#login').onclick=()=>{if(demo){staff=!staff;page='Overview';status='';render();toast(staff?'Administrator preview enabled':'Public preview: verified reports only');}else login();};}
function openReport(id){const r=reports.find(x=>x.id===id);if(!r)return;const dlg=$('#detail');dlg.innerHTML=`<div class="dialog-head"><span>REPORT DETAIL</span><button id="close" aria-label="Close report">×</button></div><div class="dialog-body"><span class="eyebrow">${esc(r.id)} · Citizen report</span><h2>${esc(events[r.event_type]||r.event_type)} in ${esc(r.location?.name||r.location_name)}</h2>${badge(r)}<p class="description">${esc(r.description)}</p><dl><dt>Event time</dt><dd>${time(r.event_time)}</dd><dt>Severity</dt><dd>${esc(r.severity||'Not specified')}</dd><dt>Coordinates</dt><dd>${r.latitude??'–'}, ${r.longitude??'–'}</dd></dl><h3>Evidence</h3>${(r.evidence||[]).map(e=>`<p class="evidence">▧ ${esc(e.type)} · ${esc(e.description)}${e.has_link?'<small>Link supplied; not automatically fetched or embedded.</small>':''}</p>`).join('')||'<p>No evidence provided.</p>'}${demo?`<div class="ai-note"><strong>✧ AI review assistant <span class="mode">Demo</span></strong><p>${esc(r.suggestion)}. This sample suggestion requires human assessment.</p></div>`:''}${staff&&(r.status==='pending'||role==='admin')?`<h3>Review decision</h3><label class="notes-label">Private review notes<textarea id="notes" placeholder="Record the evidence supporting your decision…" rows="3"></textarea></label><div class="review-actions">${r.status==='pending'?'<button class="primary" data-decision="verify">✓ Verify report</button><button class="button" data-decision="reject">Reject report</button>':r.status==='rejected'?'<button class="button" data-decision="reopen">Reopen report</button>':'<button class="button" data-decision="reject">Retract verification</button>'}</div><p id="review-error" role="alert"></p>${r.history?.length?'<h3>Review history</h3>'+r.history.map(h=>`<p>${esc(h.decision)} · ${time(h.time)}<small>${esc(h.notes)}</small></p>`).join(''):''}`:''}</div>`;dlg.showModal();$('#close').onclick=()=>dlg.close();dlg.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>review(r,b.dataset.decision));}
async function review(r,decision){const notes=$('#notes').value.trim();if(decision!=='verify'&&!notes){$('#review-error').textContent='Add review notes before rejecting or reopening a report.';return;}try{if(demo){r.status=decision==='verify'?'verified':decision==='reopen'?'pending':'rejected';r.row_version++;r.history.push({decision,notes,time:new Date().toISOString()});localStorage.setItem('monsoon-reviews',JSON.stringify(Object.fromEntries(reports.filter(x=>x.history.length).map(x=>[x.id,{status:x.status,row_version:x.row_version,history:x.history}]))));}else{const updated=await request(`/admin/reports/${encodeURIComponent(r.id)}/review`,{method:'POST',body:{decision,notes,expected_row_version:r.row_version}});Object.assign(r,updated);}$('#detail').close();renderDashboard();toast(`Report ${r.status}${demo?' · saved in demo workspace':''}`);}catch(e){$('#review-error').textContent=e.status===409?'Someone else changed this report. Close and refresh before reviewing again.':e.message;}}
function exportCSV(){const rows=[['id','event_type','location','event_time','severity','status'],...filtered().map(r=>[r.id,r.event_type,r.location?.name,r.event_time,r.severity,r.status])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='monsoon-reports.csv';a.click();URL.revokeObjectURL(url);toast('Filtered reports exported');}
function login(){if(demo){staff=!staff;status='';page='Overview';render();toast(staff?'Administrator preview enabled':'Public preview enabled');return;}const dlg=$('#detail');dlg.innerHTML='<div class="dialog-head"><h2>Staff login</h2><button id="close">×</button></div><form class="dialog-body" id="login-form"><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="primary">Sign in</button><p id="login-error" role="alert"></p></form>';dlg.showModal();$('#close').onclick=()=>dlg.close();$('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const r=await request('/auth/login',{method:'POST',body:Object.fromEntries(f)});setToken(r.access_token);role=r.user.role;staff=true;dlg.close();load();setTimeout(()=>{staff=false;setToken(null);render();toast('Session expired. Sign in again.');},r.expires_in*1000);}catch{$('#login-error').textContent='Unable to sign in. Check your credentials or try again later.';}};}
let controller;
async function load(manual=false){if(demo){lastSync=new Date();renderDashboard();if(manual)toast('Demo snapshot refreshed. No live feed is connected.');return;}controller?.abort();controller=new AbortController();loading=true;error='';renderDashboard();try{const from=new Date(Date.now()-period*86400000).toISOString(),to=new Date().toISOString();const [ls,rs]=await Promise.all([request('/locations',{signal:controller.signal}),request(`/reports?from=${from}&to=${to}&limit=200${staff?'&status=all':''}`,{signal:controller.signal})]);locations=ls.items;reports=rs.items;lastSync=new Date();if(rs.total>rs.items.length)error=`Showing the first ${rs.items.length} of ${rs.total} reports. Narrow the date range for a complete export.`;}catch(e){if(e.name==='AbortError')return;error=`${e.message}${e.request_id?' · Request '+e.request_id:''}`;}loading=false;renderDashboard();}
async function loadSources(){try{const r=await request('/analytics/summary');if($('#source-content'))$('#source-content').innerHTML=sourceRows(r.sources||[]);}catch(e){if($('#source-content'))$('#source-content').textContent=e.message;}}
window.addEventListener('monsoon-motion-change',()=>render());
window.addEventListener('session-expired',()=>{staff=false;reports=[];render();toast('Session expired. Please sign in again.');});render();if(!demo)load();setInterval(()=>{if(!demo&&!document.hidden&&!$('#detail').open&&page!=='Settings'&&page!=='Data sources')load();},30000);
